package com.sunnahcompanion.app.core.database.seed

import com.sunnahcompanion.app.core.database.model.ContentKind
import com.sunnahcompanion.app.core.database.model.DeedPriority
import com.sunnahcompanion.app.core.database.model.FardPrayer
import com.sunnahcompanion.app.core.database.model.LifeSituation
import kotlinx.serialization.Serializable

/** Shape of `assets/initial_sunnah_items.json`, generated by `tools/seed/generate_seed.py`. */
@Serializable
data class SeedBundle(
    val version: Int,
    val attribution: String,
    val items: List<SeedItem>,
    /** Habits placed in the "Active 3" slots on a fresh install. */
    val defaultActiveHabitIds: List<String>,
)

@Serializable
data class SeedItem(
    val id: String,
    val kind: ContentKind,
    val priority: DeedPriority,
    val situations: List<LifeSituation> = emptyList(),
    val anchorPrayer: FardPrayer? = null,
    val title: String,
    val arabicText: String,
    val transliteration: String,
    val translation: String,
    val audioUrl: String? = null,
    val recommendedTargetCount: Int,
    val hadithVirtue: String,
    val virtueReference: String,
    val sababAndAdabTip: String,
    val tiredModeEssential: Boolean = false,
    val sortOrder: Int,
    val surahNumber: Int? = null,
    val ayahs: List<SeedAyah> = emptyList(),
)

@Serializable
data class SeedAyah(
    val surahNumber: Int,
    val ayahNumber: Int,
    val arabicText: String,
    val transliteration: String,
    val translation: String,
    val audioUrl: String? = null,
)
